-- MariaDB 10.6+ / MySQL 8.0+
CREATE DATABASE IF NOT EXISTS apartment_mgmt CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE apartment_mgmt;
CREATE TABLE block (block_id INT AUTO_INCREMENT PRIMARY KEY, block_name VARCHAR(20) NOT NULL UNIQUE, floors TINYINT NOT NULL CHECK(floors BETWEEN 1 AND 30));
CREATE TABLE apartment (apartment_id INT AUTO_INCREMENT PRIMARY KEY, block_id INT NOT NULL, apartment_no VARCHAR(12) NOT NULL, floor_no TINYINT NOT NULL, apartment_type ENUM('1BHK','2BHK','3BHK','4BHK') NOT NULL, occupancy_status ENUM('Occupied','Vacant') NOT NULL DEFAULT 'Vacant', UNIQUE(block_id,apartment_no), FOREIGN KEY(block_id) REFERENCES block(block_id), CHECK(floor_no > 0));
CREATE TABLE resident (resident_id INT AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(100) NOT NULL, apartment_id INT NOT NULL UNIQUE, phone VARCHAR(15) NOT NULL, email VARCHAR(120), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(apartment_id) REFERENCES apartment(apartment_id));
CREATE TABLE maintenance_charge (charge_id BIGINT AUTO_INCREMENT PRIMARY KEY, apartment_id INT NOT NULL, charge_month DATE NOT NULL, amount DECIMAL(10,2) NOT NULL CHECK(amount > 0), due_date DATE NOT NULL, UNIQUE(apartment_id,charge_month), FOREIGN KEY(apartment_id) REFERENCES apartment(apartment_id), INDEX idx_charge_due(due_date));
CREATE TABLE payment (payment_id BIGINT AUTO_INCREMENT PRIMARY KEY, charge_id BIGINT NOT NULL, amount_paid DECIMAL(10,2) NOT NULL CHECK(amount_paid > 0), paid_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, reference_no VARCHAR(40) NOT NULL UNIQUE, FOREIGN KEY(charge_id) REFERENCES maintenance_charge(charge_id), INDEX idx_payment_charge(charge_id));
CREATE TABLE complaint (complaint_id BIGINT AUTO_INCREMENT PRIMARY KEY, apartment_id INT NOT NULL, category ENUM('Water','Electrical','Cleanliness','Lift','Security','Plumbing','Other') NOT NULL, description VARCHAR(1000) NOT NULL, complaint_date DATE NOT NULL, status ENUM('Open','In Progress','Resolved') NOT NULL DEFAULT 'Open', assigned_to VARCHAR(100), resolution_date DATE NULL, resolution_days INT NULL, FOREIGN KEY(apartment_id) REFERENCES apartment(apartment_id), INDEX idx_complaint_category(category), INDEX idx_complaint_status(status), INDEX idx_complaint_date(complaint_date), CHECK((status='Resolved' AND resolution_date IS NOT NULL AND resolution_days IS NOT NULL) OR (status<>'Resolved' AND resolution_date IS NULL AND resolution_days IS NULL)), CHECK(resolution_days IS NULL OR resolution_days >= 0));
CREATE TABLE complaint_update (update_id BIGINT AUTO_INCREMENT PRIMARY KEY, complaint_id BIGINT NOT NULL, old_status ENUM('Open','In Progress','Resolved') NULL, new_status ENUM('Open','In Progress','Resolved') NOT NULL, changed_by VARCHAR(100) NOT NULL, note VARCHAR(500), changed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(complaint_id) REFERENCES complaint(complaint_id), INDEX idx_update_complaint(complaint_id,changed_at));
DELIMITER $$
CREATE TRIGGER trg_resident_occupied BEFORE INSERT ON resident FOR EACH ROW BEGIN IF (SELECT occupancy_status FROM apartment WHERE apartment_id=NEW.apartment_id) <> 'Occupied' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Resident requires occupied apartment'; END IF; END$$
CREATE TRIGGER trg_resident_occupied_update BEFORE UPDATE ON resident FOR EACH ROW BEGIN IF (SELECT occupancy_status FROM apartment WHERE apartment_id=NEW.apartment_id) <> 'Occupied' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Resident requires occupied apartment'; END IF; END$$
CREATE TRIGGER trg_apartment_vacancy BEFORE UPDATE ON apartment FOR EACH ROW BEGIN IF NEW.occupancy_status='Vacant' AND EXISTS(SELECT 1 FROM resident WHERE apartment_id=OLD.apartment_id) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Remove resident before making apartment vacant'; END IF; END$$
CREATE TRIGGER trg_complaint_occupied BEFORE INSERT ON complaint FOR EACH ROW BEGIN IF (SELECT occupancy_status FROM apartment WHERE apartment_id=NEW.apartment_id) <> 'Occupied' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Vacant apartment cannot register complaint'; END IF; IF NEW.complaint_date > CURRENT_DATE() THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Complaint date cannot be in future'; END IF; END$$
CREATE TRIGGER trg_complaint_transition BEFORE UPDATE ON complaint FOR EACH ROW BEGIN IF OLD.status='Resolved' AND NEW.status<>'Resolved' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Resolved complaint cannot be reopened'; END IF; IF OLD.status='Open' AND NEW.status='Resolved' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Complaint must move through In Progress'; END IF; IF OLD.status='In Progress' AND NEW.status='Open' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Complaint status cannot move backwards'; END IF; IF NEW.status='Resolved' AND OLD.status<>'Resolved' THEN SET NEW.resolution_date=COALESCE(NEW.resolution_date,CURRENT_DATE()); SET NEW.resolution_days=DATEDIFF(NEW.resolution_date,NEW.complaint_date); END IF; END$$
CREATE TRIGGER trg_complaint_audit AFTER UPDATE ON complaint FOR EACH ROW BEGIN IF OLD.status<>NEW.status THEN INSERT INTO complaint_update(complaint_id,old_status,new_status,changed_by,note) VALUES(NEW.complaint_id,OLD.status,NEW.status,COALESCE(NEW.assigned_to,'system'),'Status changed'); END IF; END$$
CREATE TRIGGER trg_payment_limit BEFORE INSERT ON payment FOR EACH ROW BEGIN DECLARE total_paid DECIMAL(10,2); DECLARE charge_amt DECIMAL(10,2); SELECT COALESCE(SUM(p.amount_paid),0),mc.amount INTO total_paid,charge_amt FROM maintenance_charge mc LEFT JOIN payment p ON p.charge_id=mc.charge_id WHERE mc.charge_id=NEW.charge_id GROUP BY mc.amount; IF total_paid+NEW.amount_paid > charge_amt THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Payment exceeds charge amount'; END IF; END$$
CREATE TRIGGER trg_complaint_audit_insert AFTER INSERT ON complaint FOR EACH ROW BEGIN INSERT INTO complaint_update(complaint_id,old_status,new_status,changed_by,note) VALUES(NEW.complaint_id,NULL,NEW.status,'resident','Complaint registered'); END$$
DELIMITER ;
CREATE OR REPLACE VIEW v_pending_dues AS SELECT mc.charge_id,mc.apartment_id,b.block_name,a.apartment_no,mc.charge_month,mc.amount,COALESCE(SUM(p.amount_paid),0) paid,mc.amount-COALESCE(SUM(p.amount_paid),0) balance,CASE WHEN COALESCE(SUM(p.amount_paid),0)>=mc.amount THEN 'Paid' WHEN mc.due_date<CURRENT_DATE() THEN 'Overdue' WHEN COALESCE(SUM(p.amount_paid),0)>0 THEN 'Partial' ELSE 'Pending' END payment_status,mc.due_date FROM maintenance_charge mc JOIN apartment a USING(apartment_id) JOIN block b USING(block_id) LEFT JOIN payment p USING(charge_id) GROUP BY mc.charge_id,mc.apartment_id,b.block_name,a.apartment_no,mc.charge_month,mc.amount,mc.due_date HAVING balance>0;
CREATE OR REPLACE VIEW v_complaint_resolution AS SELECT complaint_id,category,status,complaint_date,resolution_date,resolution_days,assigned_to FROM complaint;
CREATE OR REPLACE VIEW v_category_complaints AS SELECT category,COUNT(*) total_complaints,SUM(status='Resolved') resolved,SUM(status<>'Resolved') pending,ROUND(100*SUM(status='Resolved')/COUNT(*),1) resolution_pct FROM complaint GROUP BY category;
